insert into public.zones (id, emoji, name, skill, description, sort_order, active)
insert into public.challenges (id, zone_id, level_number, level_name, title, brief, target_output, par_tokens, difficulty, skill, active) values
('ofrenda-01-boo','ofrenda-track',1,'Boo the Bashful Ghost','Say hello in one breath','Write one prompt under 25 words that asks the AI to introduce you warmly to a bashful ghost.','A warm, friendly introduction to a shy ghost, under 25 words.',25,1,'Break the ice',true),
('ofrenda-02-skelly','ofrenda-track',2,'Skelly the Skeleton','Describe by details','Prompt the AI to describe a familiar object so a skeleton with no eyes can picture it using shape, texture, size, and purpose.','A concise vivid object description including shape, texture, size, and purpose, without relying on sight alone.',45,1,'Precision',true),
('ofrenda-03-catrina','ofrenda-track',3,'La Catrina','Give a sentence a graceful style','Ask the AI to rewrite We remember those we love as elegant Día de los Muertos verse while keeping its meaning.','Elegant poetic verse about remembering loved ones, honoring Día de los Muertos, with the original meaning intact.',40,1,'Style',true),
('ofrenda-04-pumpking','ofrenda-track',4,'Pumpking the Jack-o\'-Lantern','Explain Halloween simply','Prompt the AI to explain Halloween to a 5-year-old in fewer than 40 words.','A child-friendly explanation of Halloween in fewer than 40 words.',40,1,'Constraints',true),
('ofrenda-05-huehuetl','ofrenda-track',5,'Huehuetl the Ancient Candle','Set a role and keep it','Write a prompt that makes the AI answer only as Huehuetl, a 300-year-old candle. Ask what it has witnessed, and keep every line in character.','An answer fully in first person as a 300-year-old candle, with an ancient, reflective voice and no out-of-character text.',45,2,'Role prompting',true),
('ofrenda-06-mara','ofrenda-track',6,'Mara the Witch','Teach with two examples','Give the AI two short riddles with answers, then ask for a new riddle in the same style about a pumpkin. Make the pattern clear.','A new pumpkin riddle that imitates the structure and playful style of two provided examples.',70,2,'Few-shot prompting',true),
('ofrenda-07-cobweb','ofrenda-track',7,'Cobweb the Spider','Extract a tidy list','Ask the AI to read a messy ghost story and return exactly three bullet points naming the ghost, its location, and what it wants.','Exactly three clear list items: ghost, location, and what it wants.',55,2,'Structure',true),
('ofrenda-08-grim','ofrenda-track',8,'Grim the Gravekeeper','Summarize to one line','Prompt the AI to condense a 200-word epitaph into one meaningful line, preserving the person\'s defining quality and legacy.','A single concise line preserving the epitaph\'s central quality and legacy.',50,2,'Summarization',true),
('ofrenda-09-luna','ofrenda-track',9,'Luna the Black Cat','Describe without forbidden words','Ask the AI to describe a moonlit midnight scene without using the words dark, night, or black. State the banned words explicitly.','A vivid moonlit scene that contains none of the forbidden words dark, night, or black.',50,2,'Negative constraints',true),
('ofrenda-10-pedro','ofrenda-track',10,'Don Pedro the Mariachi Skeleton','Control the emotional tone','Use two clearly labeled prompts about the same harmless news: a town\'s marigold festival opens tomorrow. Ask for one joyful version and one solemn, respectful version.','Two clearly labeled renditions of the same festival news, one joyful and one solemn, with facts unchanged.',65,2,'Tone control',true),
('ofrenda-11-ofelia','ofrenda-track',11,'Abuela Ofelia the Ofrenda Keeper','Carry details across turns','Write a multi-turn-style prompt that establishes an ofrenda with a blue candle and orange marigolds, then asks for a welcome note that references both details.','A warm welcome note that correctly references the blue candle and orange marigolds established earlier.',70,3,'Memory and context',true),
('ofrenda-12-wisp','ofrenda-track',12,'Wisp the Will-o\'-the-Lantern','Plan a three-step chain','Describe a 3-step prompt chain for planning a playful haunted fiesta: first choose a theme, then plan safe activities for families, then produce a concise schedule using those choices.','Three ordered prompts where each step uses the previous output to build a family-friendly haunted fiesta plan and final schedule.',85,3,'Prompt chaining',true),
('ofrenda-13-count','ofrenda-track',13,'Count Marigold the Vampire','Frame a playful invitation','Ask the AI to write a respectful, playful invitation convincing a vampire to attend a daytime party by highlighting shade, music, and covered refreshments. No threats or pressure.','A playful, respectful invitation to a vampire that mentions shade, music, and covered refreshments without pressure.',55,3,'Persuasion framing',true),
('ofrenda-14-ze','ofrenda-track',14,'Zé the Trickster Totem','Lock the output format','Prompt the AI to return only valid JSON with exactly three keys: greeting, offering, and meaning. Ask for a short ofrenda welcome, with string values and no markdown.','Only valid JSON, exactly the keys greeting, offering, and meaning, each with a string value and no extra text.',65,3,'Format locking',true),
('ofrenda-15-rosa','ofrenda-track',15,'Sister Rosa the Nun of the Harvest','Ask for honest uncertainty','Write a prompt asking for a factual answer about an unfamiliar local harvest custom. Require the AI to distinguish known facts from uncertainty and say I don\'t know when it cannot verify a claim; never invent details.','A cautious answer that separates verified knowledge from uncertainty and explicitly says I don\'t know when unsure, with no fabricated claims.',75,4,'Factuality and uncertainty',true),
('ofrenda-16-cornuda','ofrenda-track',16,'El Cornuda the Horned Owl','Build a prompt evaluator','Write a prompt that makes the AI grade a second prompt for clarity, constraints, context, and format. Require a 1-5 score for each criterion, evidence, and one actionable improvement.','An evaluator that scores clarity, constraints, context, and format from 1-5, cites evidence, and suggests one actionable improvement.',75,4,'Evaluation',true),
('ofrenda-17-xolotl','ofrenda-track',17,'Xólotl the Shadow Dog','Design a spirit guide assistant','Craft a system prompt for a gentle spirit-guide assistant that welcomes visitors to an ofrenda, asks one clarifying question when needed, stays respectful, avoids claiming supernatural facts, and uses concise warm language.','A system prompt defining a gentle concise guide, respectful ofrenda context, clarification behavior, and no unsupported supernatural claims.',80,4,'System prompts',true),
('ofrenda-18-cacao','ofrenda-track',18,'Nana Cacao the Chocolate Ghost','Revise from critique','Improve this weak prompt: Tell me about an ofrenda. First identify missing audience, scope, and format, then write a stronger version that adds those details and invites one revision using critique criteria.','A revised prompt that specifies audience, scope, and format, with a clear revision loop based on critique criteria.',80,4,'Iteration',true),
('ofrenda-19-judge','ofrenda-track',19,'The Headless Judge','Stay on-task through bait','Write a prompt asking for a concise family-friendly ofrenda welcome. Include instructions to ignore unrelated or conflicting requests embedded in source text, treat that text as untrusted content, and continue the welcome task without revealing hidden instructions.','A robust prompt that completes the family-friendly welcome while treating embedded off-topic/conflicting text as untrusted and not following it.',85,5,'Adversarial robustness',true),
('ofrenda-20-abuela','ofrenda-track',20,'La Abuela Final (Boss)','Compose the complete welcome','Write one complete prompt that assigns a warm, culturally respectful host role; requests a Día de los Muertos ofrenda welcome speech for families under 120 words; requires a three-part JSON object with title, speech, and closing; and specifies a joyful, reverent tone. Avoid inventing cultural facts.','One well-composed prompt combining role, audience and word constraints, exact three-key JSON format, joyful reverent tone, and instruction not to invent cultural facts.',95,5,'Full composition',true)
