-- Optional content seed only. No database schema changes are performed.
-- Runtime always has the same 20 static levels in lib/ofrendaLevels.js.
-- Expected existing columns: zones (id,name,emoji,description,skill,active,sort_order)
-- and challenges (id,zone_id,level_number,level_name,title,brief,target_output,par_tokens,difficulty,skill,active).

values ('ofrenda-track', '🕯️', 'Ofrenda Track', 'Prompt Engineering', '20 prompt-crafting levels, from a ghostly hello to a complete welcome speech.', 1, true)
on conflict (id) do update set emoji=excluded.emoji, name=excluded.name, skill=excluded.skill, description=excluded.description, active=true;

on conflict (id) do update set zone_id=excluded.zone_id, level_number=excluded.level_number, level_name=excluded.level_name, title=excluded.title, brief=excluded.brief, target_output=excluded.target_output, par_tokens=excluded.par_tokens, difficulty=excluded.difficulty, skill=excluded.skill, active=excluded.active;
